def create_app():
    users = {1: {'id': 1, 'name': 'Asha'}}

    def get_user(user_id):
        user = users.get(user_id)
        if user is None:
            return {'error': {'code': 'not_found', 'message': 'user missing'}}, 404
        return user, 200

    def list_users(limit=10, offset=0):
        rows = list(users.values())[offset:offset + limit]
        return {'items': rows, 'total': len(users)}, 200

    return {'get_user': get_user, 'list_users': list_users}

app = create_app()
print(app['get_user'](1))
print(app['get_user'](99))
print(app['list_users'](limit=1))

